```js
(function () {
  "use strict";

  var STORAGE_KEY = "todos.v1";
  var form = document.getElementById("new-todo");
  var input = document.getElementById("new-todo-text");
  var list = document.getElementById("todo-list");
  var empty = document.getElementById("empty");
  var count = document.getElementById("count");
  var warning = document.getElementById("storage-warning");

  var todos = load();

  function load() {
    var raw;
    try { raw = localStorage.getItem(STORAGE_KEY); } catch (err) { return []; }
    if (!raw) return [];
    try {
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (t) {
        return t && typeof t.text === "string";
      }).map(function (t) {
        return { id: String(t.id), text: t.text, done: Boolean(t.done) };
      });
    } catch (err) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
      warning.hidden = true;
      return true;
    } catch (err) {
      warning.hidden = false;
      return false;
    }
  }

  function newId() {
    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
    return Date.now().toString(36) + Math.random().toString(36).slice(2);
  }

  function itemEl(todo) {
    var li = document.createElement("li");
    li.dataset.id = todo.id;
    li.className = todo.done ? "done" : "";

    var label = document.createElement("label");
    var box = document.createElement("input");
    box.type = "checkbox";
    box.checked = todo.done;
    var text = document.createElement("span");
    text.textContent = todo.text;  // textContent: user input never parsed as HTML
    label.append(box, text);

    var remove = document.createElement("button");
    remove.type = "button";
    remove.className = "delete";
    remove.textContent = "×";
    remove.setAttribute("aria-label", "Delete " + todo.text);
    remove.title = "Delete";

    li.append(label, remove);
    return li;
  }

  function render() {
    list.replaceChildren(...todos.map(itemEl));
    empty.hidden = todos.length > 0;
    var done = todos.filter(function (t) { return t.done; }).length;
    count.textContent = todos.length ? done + " of " + todos.length + " done" : "";
  }

  function find(id) {
    return todos.find(function (t) { return t.id === id; });
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    todos.push({ id: newId(), text: text, done: false });
    input.value = "";
    input.focus();
    render();
    save();
  });

  list.addEventListener("change", function (event) {
    if (event.target.type !== "checkbox") return;
    var todo = find(event.target.closest("li").dataset.id);
    if (!todo) return;
    todo.done = event.target.checked;
    render();
    save();
  });

  list.addEventListener("click", function (event) {
    var button = event.target.closest("button.delete");
    if (!button) return;
    var id = button.closest("li").dataset.id;
    todos = todos.filter(function (t) { return t.id !== id; });
    render();
    save();
  });

  // Another tab wrote the same key: mirror it instead of overwriting on next edit.
  window.addEventListener("storage", function (event) {
    if (event.key !== STORAGE_KEY) return;
    todos = load();
    render();
  });

  render();
})();
```

